import DecaySelector from './DecaySelector';
import { Stack, ButtonGroup, Button, Modal, ModalClose, ModalDialog, Tooltip} from '@mui/joy';
import { Lock, LockOpen, QuestionMark} from '@mui/icons-material';
import FinalStateSelector from './FinalStateSelector';
import { useDispatch, useSelector } from 'react-redux';
import SaveButton from './SaveButton';
import UploadButton from './UploadButton';
import React from 'react';

export default function TopBar(){
    const dispatch = useDispatch();
    const locked = useSelector(state => state.decayLock);
    const [help, setHelp] = React.useState(false);

    const handleLockToggle = () => {
        dispatch({ type: 'TOGGLE_DECAY_LOCK' });
    }


    return (
        <React.Fragment>
        <Modal open={help} onClose={() => setHelp(false)}>
            <ModalDialog>
            <ModalClose/>
            <img
              src={
                "%PUBLIC_URL%/Help.png"
              }
              alt="help"
            />
            </ModalDialog>
        </Modal>
        <Stack spacing={2} direction="row" justifyContent={"space-between"}>
            <DecaySelector />
            <FinalStateSelector />
            <ButtonGroup>
                <Tooltip title="Help" placement="top">
                    <Button variant="outlined" onClick={() => setHelp(!help)}>
                        <QuestionMark/>
                    </Button>
                </Tooltip>
                <Tooltip title="Lock/Unlock Decay" placement="top">
                    <Button variant="outlined" onClick={handleLockToggle}>
                        {locked ? <Lock></Lock> : <LockOpen></LockOpen>}
                    </Button>
                </Tooltip>
                <SaveButton></SaveButton>
                <UploadButton></UploadButton>
            </ButtonGroup>

        </Stack>
        </React.Fragment>
    )
}