const FinalStateReducer = (state = {}, action) => {
    console.log(action);

    switch (action.type) {
        case 'SET_FINAL_STATE':
            const resetFinalStateNodes = {};
            action.payload.forEach(key => resetFinalStateNodes[key] = {spin: 0, parity: 1, name:key});
            return {"nodes": action.payload, "finalStateData": {...resetFinalStateNodes}};
        case "SET_FINAL_STATE_DATA":
            return {"nodes": state.nodes, "finalStateData": action.payload};
        default:
            return state;
    }
}

export default FinalStateReducer;