import React from 'react'
import { Graph, DefaultLink, DefaultNode } from '@visx/network';

function build_nodes(tuple, level = 1, source = null) {
  const nodes = [];
  if (level === 1){
    nodes.push(source);
  }
  for (let i = 0; i < tuple.length; i++) {
    const node = { id: JSON.stringify(tuple[i]),  source: source, level: level }
    nodes.push(node);
    if (Array.isArray(tuple[i])) {
      nodes.push(...build_nodes(tuple[i], level + 1, node));
    }
  }
  return nodes;
}

function DecayGraph(props) {
  const tuple = props.tuple;
  const root = { id: '0', x: 50, y: 50, source: null, level: 0 };
  const nodes = build_nodes(tuple, 1, root, 50, 25);

  const nNodes = tuple.flat(Infinity).length;
  const levelSlots = {};
  for (let i = 0; i < nNodes; i++) {
    levelSlots[i] = nNodes; // Key and value are both the integer
  } 

  function set_positions(node, i) {
    const level = node.level;
    const n = levelSlots[level];
    const x = (level + 1) * 40;
    const y = (-1 * n * 40)  + nNodes* 45 ;
    levelSlots[level] = n - 1;
    node.x = x;
    node.y = y;
    return node;
  }



  const unused = nodes.map((node, i) => ( set_positions(node, i) ));
  const temp_links = nodes.map((node, i) => ({ source: node.source, target: node }));
  const links = temp_links.slice(1);
  const graph = { nodes, links };
  function customNode(node_data) {
    const { node } = node_data;
    return (
      <g>
        <circle r={15}  fill='lightblue'>{node.id}</circle>
        <text   fontSize={12} dominantBaseline={"middle"} textAnchor={"middle"}>
          {node.id.replaceAll("[", "").replaceAll("]", "").replaceAll(",", "")}
        </text>
      </g>
    );
  }
  return (
    <div
      style={{
        flexGrow: 1, // Fill the parent container
        overflow: 'hidden', // Ensures SVG does not leak out
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center'
      }}
    >
      <svg overflow={"visible"} 
      style={{
        width: '90%', // Make the SVG take up the card's width
        height: '90%', // Make the SVG take up the card's height
        maxWidth: '90%', // Optional: Prevent overflow
        maxHeight: '90%', // Optional: Prevent overflow
      }}>
        <Graph graph={graph} linkComponent={DefaultLink} nodeComponent={customNode} />
      </svg>
  </div>
  )
}

export default DecayGraph;