import { Badge, Stack, Button, IconButton, Tooltip, Card, CardContent, List, ListItem } from "@mui/joy";
import { useDispatch, useSelector } from 'react-redux'
import { Avatar, Switch} from "@mui/joy";
import { Add, Delete } from "@mui/icons-material";
import { useState } from "react";


const DynamicAvatar = ({ text, onClick, selected, sx={} }) => {
    const getAvatarSize = (text) => {
      const baseSize = 40; // Default size for the Avatar
      const padding = 10; // Additional space for longer text
      const width = Math.max(baseSize, text.length * 8 + padding);
      return { width, height: baseSize };
    };
  
    const { width, height } = getAvatarSize(text);
  
    return (
      <Avatar
        onClick={onClick}
        sx={{
          width,
          height,
          borderRadius: `${height / 2}px`, // Ensure elliptical shape
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '0.875rem', // Adjust font size as needed
          padding: '0 8px', // Add padding for better text alignment
          backgroundColor: !selected ? 'primary.softBg' : 'primary.solidBg', // Custom background color
          color: !selected ? 'primary.softColor' : 'primary.solidColor', // Custom text color
        }}
      >
        {text}
      </Avatar>
    );
  };


const NodeAvatar = ({node, filter, setCurrentFilter, finalStateData}) => {
    const { spin: j, parity: p, name: nm } = finalStateData[node];
    return (
        <DynamicAvatar onClick={() => setCurrentFilter({...filter, [node]: !filter[node]})} text = {nm} selected={filter[node]}>
        </DynamicAvatar>
    )
}


function FilterBar({ filter, setFilter }) {
  const finalStateNodes = useSelector((state) => state.finalState.nodes);
  const finalStateData = useSelector((state) => state.finalState.finalStateData);

  const [currentFilter, setCurrentFilter] = useState({});
  const currentFilterKeys = Object.keys(currentFilter).filter((key) => currentFilter[key]);
  currentFilterKeys.sort();
  const currentFilterName = "[" + currentFilterKeys.join(",") + "]";
  return (
    <Stack spacing={2} direction="column" justifyContent={"space-between"} alignItems={"center"}
    sx={{border: "1px solid #ccc", borderRadius: "0.5rem"}}>
        <Stack spacing={1} direction="row" justifyContent={"space-between"} alignItems={"center"} 
            sx={{padding: "0.5rem", width: "100%", flexWrap: "wrap", rowGap: "0.5rem"}}>
            {
                finalStateNodes.map((node) => {
                    return (
                        <NodeAvatar node={node} filter={currentFilter} setCurrentFilter={setCurrentFilter} finalStateData={finalStateData}/>
                    )
                })
            }
            <Tooltip title="Add the filter to the filter list">
            <IconButton  color="primary" sx={{backgroundColor: "#eee"}} onClick={() => setFilter({...filter, [currentFilterName]: {...currentFilter}})} disabled={currentFilterKeys.length === 0 || currentFilterKeys.length === 1 || currentFilterKeys.length === finalStateNodes.length}> 
                <Add />
            </IconButton>
            </Tooltip>
        </Stack>
              <List sx={{width: "100%", height: "10vh", overflowY: "auto", border: "1px solid #ccc"}}>
            {
                Object.keys(filter).map((key) => {
                    return (
                        <ListItem>
                        <Stack spacing={1} direction="row" justifyContent={"space-between"} alignItems={"center"} 
                        sx={{padding: "0.5rem", width: "100%", flexWrap: "wrap", rowGap: "0.5rem"}} >
                            {
                                finalStateNodes.map((node) => {
                                    return (
                                        <NodeAvatar node={node} filter={filter[key]} setCurrentFilter={() => {}} finalStateData={finalStateData}/>
                                    )
                                })
                            }
                            <Tooltip title="Remove the filter from the filter list">
                            <IconButton  color="danger" onClick={() =>{
                                const {...newFilter} = filter;
                                delete newFilter[key];
                                setFilter({...newFilter});
                            }}> 
                                <Delete />
                            </IconButton>
                            </Tooltip>
                        </Stack>
                        </ListItem>
                    )
                }
            )
            }
            </List>
    </Stack>
  );
}

export default FilterBar;