import { Grid, Card, Select, CardContent, Button, Stack, CircularProgress } from '@mui/joy';
import DecayGraph from './Graph';
import List from '@mui/joy/List';
import ListItem from '@mui/joy/ListItem';
import ListItemButton from '@mui/joy/ListItemButton';
import Option from '@mui/joy/Option';
import { FixedSizeList } from 'react-window';
import { useSelector, useDispatch } from 'react-redux'
import { useState, useEffect } from 'react';
import FilterBar from './FilterBar';
import { API_PATH } from '../Internal/api.js';


export default function TreeList() {

    const [containerHeight, setContainerHeight] = useState(window.innerHeight * 0.9); // Default to 90vh
    const [filter, setFilter] = useState({});
    const [filterReady, setFilterReady] = useState(false);
    const [filteredTopologies, setFilteredTopologies] = useState([]);
    const mainGraph = useSelector((state) => state.mainGraph);
    const n = useSelector((state) => state.decay);
    useEffect(() => {
        // Recalculate height on window resize
        const handleResize = () => {
            setContainerHeight(window.innerHeight * 0.9); // Update height dynamically
        };

        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    useEffect(() => {
        setFilterReady(false);
        setFilter({});
        setFilteredTopologies([]);
    }, [n]);

    const graphs = useSelector((state) => state.graph);
    

    const dispatch = useDispatch();
    const handleGraphCardClick = (tuple) => {
        dispatch({ type: 'SET_MAIN_GRAPH', payload: tuple });
    };

    if (!graphs.hasOwnProperty('topologies')) {
        return (
            <List>
            </List>
        );
    }
    if (!filterReady && !(Object.keys(filter).length === 0)) {
        return (
            <CircularProgress />
        )
    }




    const ChangeFilter = ( filter ) => {
        setFilter(filter);
        setFilterReady(false);

        const filterString = "[" + Object.keys(filter).map((key) => {
            return key;
        }).join(",") + "]";
        const api_query = API_PATH + "filtered?n="+ n + "&filter=" + filterString;
        fetch(api_query)
        .then(response => {
            if (!response.ok) {
            throw new Error('Network response was not ok');
            }
            return response.json();
        })
        .then(data => {
            setFilteredTopologies(data.topologies);
            setFilterReady(true);
        })
        .catch(error => {
            console.error('Error:', error);
        });
    }

    const items = filterReady ? filteredTopologies : graphs.topologies;

    const buttonComponent = ({index}) => {
        return (
            <Card variant={(mainGraph.tuple == items[index]) ? 'soft' : 'outlined'}  color={(mainGraph.tuple == items[index]) ? 'primary' : 'neutral'}   sx={{
                width: '100%', // Ensures the Card takes up full button width
                border: (mainGraph.tuple == items[index]) ? '4px solid #ccc' : '1px solid #ccc', // Optional: for visualization
              }}>
                <DecayGraph tuple={items[index]} />
            </Card>
        )
    }

    const Row = ({ index, style }) => (
        <ListItem style={{...style}} >
            <ListItemButton onClick={() => handleGraphCardClick(items[index])}   >
            {/* <Card variant={(mainGraph.tuple == items[index]) ? 'solid' : 'outlined'}>
                <DecayGraph tuple={items[index]} />
            </Card> */}
            {buttonComponent({index})}
            </ListItemButton>
         </ListItem>
    );



    return (
        <Stack direction="column" spacing={2}>
            <FilterBar setFilter={ChangeFilter} filter={filter} />
        <List sx={{
            maxHeight: '90vh', // Set a fixed height for the list
            overflowY: 'auto', // Enable vertical scrolling
            // border: '1px solid #ccc', // Optional: for visualization
            // padding: '1rem', // Optional: for styling
            // width: '300px', // Optional: set a fixed width for the list
          }}>
            <FixedSizeList
                height={containerHeight} // Total height of the list container
                itemCount={items.length} // Total items
                itemSize={200} // Height of each item
                width="100%" // Match List width
            >
            {
                Row
            }
            </FixedSizeList>
            </List>
        </Stack>

    );
    }